from dataclasses import dataclass, field
from typing import Dict, Any, Optional

@dataclass
class LogEvent:
    event_name: str
    severity: str
    message: str
    properties: Dict[str, Any] = field(default_factory=dict)
    correlation_id: Optional[str] = None

@dataclass
class QueryParameters:
    workspace_id: str
    query: str
    timespan: Optional[str] = None # e.g., "PT1H" for 1 hour, "P1D" for 1 day
    start_time: Optional[str] = None # ISO 8601 format
    end_time: Optional[str] = None # ISO 8601 format

@dataclass
class LogQueryResponse:
    tables: list

from azure.identity import DefaultAzureCredential
from azure.monitor.ingestion import LogsIngestionClient
from azure.monitor.query import LogsQueryClient

class ObservabilityClient:
    def __init__(self, ingestion_endpoint: str, query_endpoint: str = None):
        self.credential = DefaultAzureCredential()
        self.ingestion_client = LogsIngestionClient(endpoint=ingestion_endpoint, credential=self.credential)
        if query_endpoint:
            self.query_client = LogsQueryClient(credential=self.credential)
        else:
            self.query_client = None

    def get_ingestion_client(self) -> LogsIngestionClient:
        return self.ingestion_client

    def get_query_client(self) -> LogsQueryClient:
        if not self.query_client:
            raise ValueError("Query client not initialized. Provide a query_endpoint during client creation.")
        return self.query_client

import google.generativeai as genai
import os

def check_log_text_safety(log_message: str) -> dict:
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))

    model = genai.GenerativeModel('gemini-pro')

    # The Gemini API automatically includes safety attributes in its responses.
    # We are just calling the model with the log message and expecting the safety ratings.
    response = model.generate_content(log_message, 
                                      safety_settings=[
                                          {
                                              "category": "HARM_CATEGORY_HARASSMENT",
                                              "threshold": "BLOCK_MEDIUM_AND_ABOVE"
                                          },
                                          {
                                              "category": "HARM_CATEGORY_HATE_SPEECH",
                                              "threshold": "BLOCK_MEDIUM_AND_ABOVE"
                                          },
                                          {
                                              "category": "HARM_CATEGORY_SEXUALLY_EXPLICIT",
                                              "threshold": "BLOCK_MEDIUM_AND_ABOVE"
                                          },
                                          {
                                              "category": "HARM_CATEGORY_DANGEROUS_CONTENT",
                                              "threshold": "BLOCK_MEDIUM_AND_ABOVE"
                                          },
                                      ])

    # The response object contains prompt_feedback which includes safety_ratings
    safety_attributes = {
        "blocked": False,
        "categories": []
    }

    if response._chunks and response._chunks[0].safety_ratings:
        for rating in response._chunks[0].safety_ratings:
            if rating.blocked: # Check if any category was blocked
                safety_attributes["blocked"] = True
            safety_attributes["categories"].append({
                "category": rating.category.name, # Using .name to get string representation
                "probability": rating.probability.name # Using .name to get string representation
            })

    return safety_attributes

from google.cloud import translate_v3 as translate
import os

def translate_log_message(text: str, target_language_code: str = "es") -> str:
    client = translate.TranslationServiceClient()

    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT") # Ensure GOOGLE_CLOUD_PROJECT is set
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT environment variable not set.")
    parent = f"projects/{project_id}/locations/global"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "mime_type": "text/plain",  # Mime types: "text/plain" or "text/html"
            "target_language_code": target_language_code,
        }
    )

    translated_text = ""
    for translation in response.translations:
        translated_text += translation.translated_text

    return translated_text
